function CS_t(key){return CS_TX[currentLang]?.[key]||CS_TX.en[key]||key;}
function CS_lang(){return currentLang==='ar'?'ar':'en';}
function CS_now(){return new Date().toISOString().slice(0,10);}
function CS_uid(){return globalThis.crypto?.randomUUID?.()||`cs-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function CS_initState(){
 projectBrain.construction=projectBrain.construction&&typeof projectBrain.construction==='object'?projectBrain.construction:{};
 const c=projectBrain.construction;
 for(const key of ['records','checklists','checklistTemplates','activityNotes','chatHistory'])if(!Array.isArray(c[key]))c[key]=[];
 c.preferences=c.preferences&&typeof c.preferences==='object'?c.preferences:{aiLanguage:CS_lang(),reportLanguage:'bilingual',explanationLevel:'professional'};
 c.selectedActivity=c.selectedActivity||CS_RAW[0].activities[0].id;
}
CS_initState();
function CS_save(){
 CS_initState();try{localStorage.setItem('archmindProjectBrain',JSON.stringify(projectBrain));}catch{if(typeof toast==='function')toast(CS_t('saveFailed'));}
 if(typeof persistProject==='function')persistProject();
 const saved=document.getElementById('csSaved');if(saved){saved.textContent=CS_t('saved');saved.dataset.at=String(Date.now());}
 CS_renderStats();
}
function CS_activity(id){for(const p of CS_RAW){const a=p.activities.find(x=>x.id===id);if(a)return {phase:p,activity:a};}return null;}
function CS_esc(x){return typeof esc==='function'?esc(String(x??'')):String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function CS_labels(){return CS_RAW.map(p=>({id:p.id,title:p[CS_lang()],activities:p.activities.map(a=>({id:a.id,title:a[CS_lang()]}))}));}
function CS_renderNav(){
 const nav=document.getElementById('constructionNav');if(nav)nav.textContent=CS_t('nav');
 const title=document.getElementById('csTitle');if(title)title.textContent=CS_t('title');
 const sub=document.getElementById('csSub');if(sub)sub.textContent=CS_t('sub');
 const guide=document.getElementById('csGuidance');if(guide)guide.textContent=CS_t('guidance');
 document.querySelectorAll('[data-cs-label]').forEach(el=>el.textContent=CS_t(el.dataset.csLabel));const chatInput=document.getElementById('csChatInput');if(chatInput)chatInput.placeholder=CS_t('chatPlaceholder');
 const ai=document.getElementById('aiMode');if(ai){let opt=ai.querySelector('option[value="site_engineer"]');if(opt)opt.textContent=CS_lang()==='ar'?'مهندس موقع ذكي':'AI Site Engineer';}
 CS_renderPhases();CS_renderActivity();CS_renderRecords();CS_renderStats();CS_renderTabs();
}
function CS_renderTabs(){document.querySelectorAll('[data-cs-tab]').forEach(b=>b.classList.toggle('active',b.dataset.csTab===(document.getElementById('csActiveTab')?.value||'workflow')));}
function CS_renderPhases(){
 const host=document.getElementById('csPhases');if(!host)return;
 const q=(document.getElementById('csSearch')?.value||'').trim().toLocaleLowerCase();const phaseFilter=document.getElementById('csPhaseFilter')?.value||'';const statusFilter=document.getElementById('csStatusFilter')?.value||'';
 const done=new Set(CS_RAW.flatMap(p=>p.activities).filter(a=>projectBrain.construction?.activityStatus?.[a.id]==='complete'||CS_checkRows(a.id).filter(x=>x.status!=='na').length>0&&CS_checkRows(a.id).filter(x=>x.status!=='na').every(x=>x.status==='compliant')).map(a=>a.id));
 const phaseMatches=CS_RAW.filter(p=>(!phaseFilter||p.id===phaseFilter)&&p.activities.some(a=>`${p.en} ${p.ar} ${a.en} ${a.ar}`.toLocaleLowerCase().includes(q)||!q));
 if(!phaseMatches.length){host.innerHTML=`<div class="cs-empty">${CS_t('searchEmpty')}</div>`;return;}
 host.innerHTML=phaseMatches.map(p=>`<details class="cs-phase" data-phase="${p.id}" ${p.activities.some(a=>a.id===projectBrain.construction.selectedActivity)?'open':''}><summary><span class="cs-phase-no">${String(p.index).padStart(2,'0')}</span><span class="cs-phase-title">${CS_esc(p[CS_lang()])}</span><span class="cs-phase-count">${p.activities.filter(a=>done.has(a.id)).length}/${p.activities.length}</span></summary><div class="cs-activity-list">${p.activities.filter(a=>`${a.en} ${a.ar}`.toLocaleLowerCase().includes(q)||!q).filter(a=>!statusFilter||done.has(a.id)===(statusFilter==='done')).map(a=>`<button type="button" class="cs-activity ${a.id===projectBrain.construction.selectedActivity?'is-selected':''}" data-cs-activity="${a.id}"><span><b>${CS_esc(a[CS_lang()])}</b><small>${CS_esc(p[CS_lang()])}</small></span><i class="cs-dot ${done.has(a.id)?'is-done':''}" title="${done.has(a.id)?CS_t('compliant'):CS_t('notStarted')}"></i></button>`).join('')}</div></details>`).join('');
 host.querySelectorAll('[data-cs-activity]').forEach(b=>b.addEventListener('click',()=>{projectBrain.construction.selectedActivity=b.dataset.csActivity;CS_save();CS_renderPhases();CS_renderActivity();}));
}
function CS_seedChecklist(activityId){
 const c=projectBrain.construction;let rows=c.checklists.filter(x=>x.activityId===activityId);if(rows.length)return rows;
 const data=CS_activity(activityId);if(!data)return [];
 const initial=[
  ['Confirm latest approved drawings and revision','تحقق من أحدث الرسومات المعتمدة ومراجعتها','Current approved revision is available at the workface.','المراجعة المعتمدة الحالية متاحة في موقع العمل.'],
  ['Confirm prerequisites, permits and approved method','تحقق من المتطلبات السابقة والتصاريح والمنهجية المعتمدة','Required approvals, access, setting out and preceding activities are ready.','الاعتمادات والوصول والمحاور والأنشطة السابقة اللازمة جاهزة.'],
  ['Inspect workmanship and record measurable evidence','افحص جودة التنفيذ وسجّل أدلة قابلة للقياس','Record actual values, location, reference and evidence against project criteria.','سجّل القيم الفعلية والموقع والمرجع والدليل مقابل معايير المشروع.'],
  ['Complete required inspection before covering or proceeding','أكمل الفحص المطلوب قبل الإغلاق أو الانتقال','Identify hold / witness points from the approved ITP; do not conceal work before release.','حدّد نقاط التوقف والشهود من ITP المعتمدة ولا تغطِ العمل قبل الإفراج عنه.']
 ];
 rows=initial.map(([en,ar,ve,va],i)=>({id:CS_uid(),activityId,itemEn:en,itemAr:ar,verifyEn:ve,verifyAr:va,reference:'',responsible:'Contractor QA/QC',status:'notStarted',notes:'',inspector:'',date:'',photo:'',isGeneral:true,order:i}));
 c.checklists.push(...rows);CS_save();return rows;
}
function CS_guide(data){
 const a=data.activity,p=data.phase,l=CS_lang();const ar=l==='ar';
 const docs=ar?['رسومات IFC أو رسومات تنفيذية معتمدة IFC = رسومات صادرة للتنفيذ.','مواصفات المشروع واعتماد المادة ومنهجية التنفيذ.','خطة الفحص والاختبار ITP وتقييم المخاطر والتنسيق المرتبط.','تصريح العمل والسجلات السابقة ومراجعة الرسم عند الاقتضاء.']:['Latest approved IFC / shop drawings (IFC = Issued for Construction).','Project specifications, approved material submittal and method statement.','Inspection and Test Plan (ITP), risk assessment and relevant coordination drawings.','Permit to work, preceding records and drawing revision where applicable.'];
 const mat=ar?['المواد المعتمدة للنشاط، بعد مطابقة المورد والدفعة والبيانات الفنية.','أدوات القياس والفحص المعايرة، ومعدات الوصول والرفع المناسبة للموقع.','تُخصص القائمة بحسب المشروع والموقع ولا تفترض أن موردًا أو معدة بعينها مطلوبة دائمًا.']:['Approved activity materials checked against supplier, batch and technical submittal.','Calibrated measuring / test equipment and suitable access or lifting equipment.','Customize to the project and site; no particular product or equipment is assumed.'];
 const steps=ar?[`راجع نطاق «${a.ar}» وحدود العمل والرسم المعتمد والمراجعة الحالية.`,`تحقق من المتطلبات السابقة والتصاريح والمواد والعمالة ونقاط التنسيق قبل بدء النشاط.`,`نفّذ العمل وفق منهجية المشروع المعتمدة؛ وثّق القياسات والتغييرات ولا تتجاوز نقطة توقف.`,`أجرِ فحص المقاول الداخلي وسجّل النتائج والأدلة والعيوب قبل طلب IR عند اشتراطه.`,`عالج الملاحظات، اطلب الفحص المطلوب، وسجّل الإفراج قبل الإغلاق أو الانتقال.`]:[`Confirm the scope for “${a.en}”, approved drawing and current revision.`,`Check prerequisites, permits, approved materials, resources and discipline interfaces before starting.`,`Execute to the project-approved method; record measurements and changes, and do not pass a hold point.`,`Complete contractor self-check and evidence before raising an IR where required.`,`Close comments, obtain required inspection release, and record it before covering or proceeding.`];
 const discipline=a.discipline==='mep'?(ar?'العمارة والإنشاء والحريق والتشغيل والتخصصات المعنية.':'Architecture, structure, fire/life safety, commissioning and relevant specialists.'):a.discipline==='structure'?(ar?'العمارة والكهروميكانيك والمدني والمساح وفريق الصب عند الاقتضاء.':'Architecture, MEP, civil, survey and concrete team where applicable.'):ar?'العمارة والإنشاء والكهروميكانيك والحريق ومقاولو التخصصات.':'Architecture, structure, MEP, fire/life safety and specialist subcontractors.';
 const executionAr=['تحقق من المواد الواردة ومصدرها وظروف التخزين واعتمادها قبل الاستخدام.','تحقق من المحاور والمناسيب والأبعاد مع مرجع مساحي/رسم معتمد، وسجل أي تعارض.','نسّق الفتحات والدعامات والخدمات والتخصصات قبل تنفيذ الجزء الذي سيُغطى.','نفّذ على مراحل مع فحوص داخلية موثقة وفق نقاط الفحص المعتمدة بالمشروع.','نظّف الموقع واحمِ الأعمال وسجّل رقم الطلب والنتيجة والإجراء التالي.'];
 const executionEn=['Verify delivered materials, source, storage condition and approval before use.','Check setting out, levels and dimensions against an approved drawing / survey reference; record discrepancies.','Coordinate openings, supports and services before completing work that will be concealed.','Work in controlled stages with documented self-checks at the project-approved inspection points.','Clean and protect completed work; record request reference, result and next action.'];
 const qA=['راجع معيار القبول المعلن في المواصفة/الرسم، لا معيارًا مفترضًا.','افحص المقاس والاستقامة والمنسوب والتثبيت وسلامة المادة بحسب طبيعة النشاط.','سجّل نتائج الاختبارات والأجهزة ورقم المعايرة والدفعة والموقع عند انطباقها.','لا تغلق الأعمال المخفية قبل استكمال فحصها وتوثيقها والإفراج عنها.'];
 const qE=['Check acceptance criteria in the actual specification / drawing, not an assumed generic tolerance.','Inspect dimensions, alignment, level, fixing and material condition as relevant to the activity.','Record test results, equipment / calibration, batch and location where applicable.','Do not conceal work until inspection, evidence and required release are complete.'];
 const issueA=['اختلاف مراجعة الرسم في الموقع: أوقف الجزء المتأثر وسجل رقم الرسم وأرسل RFI عند الحاجة.','تعارض خدمة أو فتحة: وثّق الموقع والأبعاد والصور واطلب تنسيقًا؛ لا تنقلها من تلقاء نفسك.','نقص اعتماد أو فحص: سجل المفقود والمسؤول والموعد، ولا تصف البند بأنه معتمد.','عيب جودة: سجل الحالة والدليل والمرجع وأصدر ملاحظة/NCR وفق إجراء المشروع.'];
 const issueE=['Drawing revision mismatch: stop affected work, log the drawing number and raise an RFI if needed.','Service / opening clash: record location, dimensions and photos, then obtain coordination; do not relocate it unilaterally.','Missing approval / inspection: record the gap, owner and date; do not call the item approved.','Quality defect: log condition, evidence and reference; raise an observation / NCR per project procedure.'];
 return [
  ['overviewLabel',ar?`${a.ar} نشاط ضمن مرحلة «${p.ar}». يُستخدم حيثما نص نطاق المشروع والرسومات والمواصفات المعتمدة على ذلك.`:`${a.en} is an activity in ${p.en}. Use only where required by this project's scope, approved drawings and specifications.`],
  ['purpose',ar?`الغرض الهندسي هو إنجاز «${a.ar}» بأمان وبجودة قابلة للتحقق، وربطه بالأنشطة السابقة واللاحقة دون إخفاء تعارض أو افتراض اعتماد.`:`The engineering purpose is to complete ${a.en} safely with verifiable quality, coordinating its interfaces without hiding conflicts or assuming approval.`],
  ['documents',ar?'المراجع النموذجية (تُتحقق بحسب العقد والمواصفات وإجراءات المشروع):':'Typical references (confirm against contract, specifications and project procedures):',docs],
  ['materials',ar?'موارد نموذجية قابلة للتخصيص حسب المشروع:':'Typical resources; customize to the project:',mat],
  ['execution',ar?'تسلسل عام مبسط — المرجع الحاكم هو منهجية التنفيذ المعتمدة:':'Simple general sequence — the approved project method statement governs:',steps.concat(ar?executionAr:executionEn)],
  ['quality',ar?'ما يجب ضبطه:':'Quality checks:',ar?qA:qE],
  ['inspection',ar?'الفحص والاستلام:':'Inspection and acceptance:',[ar?'يبدأ المقاول بفحصه الداخلي وتوثيق الجاهزية قبل طلب IR (Inspection Request = طلب فحص) إذا تطلبت الإجراءات ذلك.':'The contractor completes and records its internal check before raising an IR (Inspection Request) where the procedure requires it.',ar?`المشاركون المعتادون: ${CS_TX.ar.participant}`:`Typical participants: ${CS_TX.en.participant}`,ar?'أرفق القائمة المكتملة والمراجع والنتائج والصور ذات الصلة. سجّل التعليقات والنتيجة والمسؤول والموعد. عند الرفض، صحح ثم اطلب إعادة الفحص وسجل الإغلاق.':'Attach checklist, references, results and relevant photos. Record comments, result, owner and date. If rejected, correct, request re-inspection and record closure.']],
  ['safety',ar?'السلامة:':'Safety:',[ar?'حدّد مخاطر الرفع والسقوط والكهرباء والحفر والمواد وحركة المعدات حسب النشاط والموقع.':'Assess lifting, falls, electricity, excavation, materials and plant movement hazards for this activity and location.',ar?'استخدم تقييم المخاطر وتصريح العمل وخطة HSE المعتمدة والإشراف المختص؛ هذا الشرح لا يحل محلها.':'Follow the approved risk assessment, permit-to-work and HSE plan under competent supervision; this guide does not replace them.']],
  ['coordination',ar?'التنسيق:':'Coordination:',[discipline,ar?'راجع الواجهات والمناسيب والفتحات والتسلسل والوصول قبل التنفيذ؛ سجل التعارضات وأرسل RFI عند غموض التصميم.':'Confirm interfaces, levels, openings, sequence and access before work; record clashes and raise an RFI when design intent is unclear.']],
  ['completion',ar?'يُغلق النشاط عندما تكتمل الأعمال والفحوص والسجلات والتصحيحات المطلوبة، وتُحفظ نتيجة الفحص/الإفراج حسب الإجراء المعتمد. لا يعني ذلك وحده اعتماد الجهة أو الاستشاري.':'Close after the scope, checks, records and required corrections are complete and inspection / release is recorded per procedure. This alone does not assert authority or consultant approval.'],
  ['issues',ar?'أمثلة تستوجب التحقيق والتوثيق:':'Examples to investigate and document:',ar?issueA:issueE],
  ['next',ar?`المرحلة التالية غالبًا نشاط تابع في «${p.ar}» أو المرحلة اللاحقة. تحقّق من الاعتمادات والمتطلبات السابقة ونقاط الفحص والإفراج قبل المتابعة.`:`Next may be a follow-on activity in ${p.en} or the next phase. Confirm approvals, prerequisites, inspection points and releases before proceeding.`]
 ];
}
function CS_renderActivity(){
 const root=document.getElementById('csActivityGuide');if(!root)return;const data=CS_activity(projectBrain.construction.selectedActivity);if(!data){root.innerHTML=`<div class="cs-empty">${CS_t('chooseActivity')}</div>`;return;}
 const a=data.activity,p=data.phase,l=CS_lang();CS_seedChecklist(a.id);const guide=CS_guide(data);
 root.innerHTML=`<div class="cs-selected-head"><div><div class="cs-eyebrow">${String(p.index).padStart(2,'0')} / ${CS_t('phase')} · ${CS_esc(p[l])}</div><h2>${CS_esc(a[l])}</h2><div class="cs-meta">${CS_t('general')} · ${a.discipline==='mep'?'MEP':a.discipline==='structure'?(l==='ar'?'إنشاء':'Structure'):(l==='ar'?'عام':'General')}</div></div><div class="cs-row-actions"><button class="btn small" type="button" onclick="CS_ai('activity')">${CS_t('aiExplain')}</button><button class="btn small" type="button" onclick="CS_ai('translate')">${CS_t('translate')}</button><button class="btn small" type="button" onclick="CS_completeActivity()">✓ ${CS_t('done')}</button></div></div><div class="cs-guide-grid">${guide.map(([key,lead,items])=>`<details class="cs-guide-item" ${['overviewLabel','execution','inspection'].includes(key)?'open':''}><summary>${CS_t(key)}</summary><div class="cs-guide-body">${typeof lead==='string'?`<p>${CS_esc(lead)}</p>`:''}${Array.isArray(items)?`<ul>${items.map(x=>`<li>${CS_esc(x)}</li>`).join('')}</ul>`:''}</div></details>`).join('')}</div><div class="cs-caution">${CS_t('guidance')}</div><section class="cs-checks"><div class="cs-section-head"><div><span class="cs-eyebrow">${CS_t('general')}</span><h3>${CS_t('checklist')}</h3><p>${CS_t('completionNote')}</p></div><div class="cs-row-actions"><select class="input cs-template-select" id="csTemplateSelect"><option value="">${CS_t('useTemplate')}</option>${projectBrain.construction.checklistTemplates.map(x=>`<option value="${CS_esc(x.id)}">${CS_esc(x.name)}</option>`).join('')}</select><button class="btn small" type="button" onclick="CS_applyTemplate()">${CS_t('apply')}</button><button class="btn small" type="button" onclick="CS_saveTemplate()">${CS_t('saveTemplate')}</button><button class="btn primary small" type="button" onclick="document.getElementById('csNewChecklist').hidden=false">+ ${CS_t('addChecklist')}</button></div></div><div class="cs-new-check" id="csNewChecklist" hidden><label>${CS_t('item')} · EN<input class="input" id="csNewCheckEn"></label><label>${CS_t('item')} · عربي<input class="input" id="csNewCheckAr" dir="rtl"></label><label>${CS_t('verify')} · EN<input class="input" id="csNewVerifyEn"></label><label>${CS_t('verify')} · عربي<input class="input" id="csNewVerifyAr" dir="rtl"></label><label>${CS_t('reference')}<input class="input" id="csNewReference"></label><label>${CS_t('responsible')}<input class="input" id="csNewResponsible"></label><button class="btn primary small" type="button" onclick="CS_addChecklist()">${CS_t('add')}</button><button class="btn small" type="button" onclick="document.getElementById('csNewChecklist').hidden=true">${CS_t('cancel')}</button></div><div id="csChecklistList"></div></section>`;
 CS_renderChecklist(a.id);
}
function CS_checkRows(activityId){return projectBrain.construction.checklists.filter(x=>x.activityId===activityId).sort((a,b)=>(a.order||0)-(b.order||0));}
function CS_renderChecklist(activityId){
 const root=document.getElementById('csChecklistList');if(!root)return;const ar=CS_lang()==='ar';const rows=CS_checkRows(activityId);
 root.innerHTML=rows.map((x,i)=>`<article class="cs-check-row" data-check="${x.id}"><div class="cs-check-top"><b>${i+1}. ${CS_esc(ar?x.itemAr||x.itemEn:x.itemEn||x.itemAr)}</b><span class="cs-general-tag">${x.isGeneral?CS_t('general'):''}</span><button class="cs-text-button" type="button" onclick="CS_deleteChecklist('${x.id}')">${CS_t('remove')}</button></div><div class="cs-check-grid cs-check-edit"><label>${CS_t('item')} · EN<input class="input" data-f="itemEn" value="${CS_esc(x.itemEn)}"></label><label>${CS_t('item')} · عربي<input class="input" dir="rtl" data-f="itemAr" value="${CS_esc(x.itemAr)}"></label><label>${CS_t('verify')} · EN<input class="input" data-f="verifyEn" value="${CS_esc(x.verifyEn)}"></label><label>${CS_t('verify')} · عربي<input class="input" dir="rtl" data-f="verifyAr" value="${CS_esc(x.verifyAr)}"></label><label>${CS_t('reference')}<input class="input" data-f="reference" value="${CS_esc(x.reference)}"></label><label>${CS_t('responsible')}<input class="input" data-f="responsible" value="${CS_esc(x.responsible)}"></label><label>${CS_t('status')}<select class="input" data-f="status">${CS_STATUSES.map(s=>`<option value="${s}" ${x.status===s?'selected':''}>${CS_t(s)}</option>`).join('')}</select></label><label>${CS_t('date')}<input class="input" type="date" data-f="date" value="${CS_esc(x.date)}"></label><label>${CS_t('inspector')}<input class="input" data-f="inspector" value="${CS_esc(x.inspector)}"></label><label>${CS_t('notes')}<input class="input" data-f="notes" value="${CS_esc(x.notes)}"></label></div><label class="cs-photo-label">${CS_t('photo')} · ${CS_t('photosOnly')}<input type="file" accept="image/*" data-cs-photo="${x.id}"><span>${x.photo?CS_esc(x.photoName||CS_t('uploadPhoto')):''}</span></label>${x.photo?`<img class="cs-photo-thumb" src="${x.photo}" alt="${CS_t('photo')}">`:''}</article>`).join('');
 root.querySelectorAll('.cs-check-row').forEach(row=>row.querySelectorAll('[data-f]').forEach(input=>input.addEventListener('change',()=>{const x=projectBrain.construction.checklists.find(z=>z.id===row.dataset.check);if(x){x[input.dataset.f]=input.value;CS_save();}})));
 root.querySelectorAll('[data-cs-photo]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const x=projectBrain.construction.checklists.find(z=>z.id===input.dataset.csPhoto);if(!x)return;try{x.photo=await CS_compressPhoto(file);x.photoName=file.name;CS_save();CS_renderChecklist(activityId);}catch{toast(CS_t('photosOnly'));}}));
}
function CS_addChecklist(){const d=CS_activity(projectBrain.construction.selectedActivity);if(!d)return;const itemEn=document.getElementById('csNewCheckEn')?.value.trim(),itemAr=document.getElementById('csNewCheckAr')?.value.trim();if(!itemEn&&!itemAr)return toast(CS_t('item'));projectBrain.construction.checklists.push({id:CS_uid(),activityId:d.activity.id,itemEn:itemEn||itemAr,itemAr:itemAr||itemEn,verifyEn:document.getElementById('csNewVerifyEn')?.value.trim()||'',verifyAr:document.getElementById('csNewVerifyAr')?.value.trim()||'',reference:document.getElementById('csNewReference')?.value.trim()||'',responsible:document.getElementById('csNewResponsible')?.value.trim()||'',status:'notStarted',notes:'',inspector:'',date:'',photo:'',isGeneral:false,order:Date.now()});CS_save();CS_renderActivity();}
function CS_deleteChecklist(id){projectBrain.construction.checklists=projectBrain.construction.checklists.filter(x=>x.id!==id);CS_save();CS_renderActivity();}
function CS_saveTemplate(){const name=prompt(CS_lang()==='ar'?'اسم قالب القائمة':'Checklist template name');if(!name?.trim())return;const data=CS_checkRows(projectBrain.construction.selectedActivity).map(({id,activityId,photo,photoName,...x})=>({...x,id:undefined,activityId:undefined}));projectBrain.construction.checklistTemplates.push({id:CS_uid(),name:name.trim(),items:data});CS_save();CS_renderActivity();toast(CS_t('templateSaved'));}
function CS_applyTemplate(){const id=document.getElementById('csTemplateSelect')?.value;const template=projectBrain.construction.checklistTemplates.find(x=>x.id===id);if(!template)return;const activityId=projectBrain.construction.selectedActivity;projectBrain.construction.checklists=projectBrain.construction.checklists.filter(x=>x.activityId!==activityId);projectBrain.construction.checklists.push(...template.items.map(x=>({...x,id:CS_uid(),activityId,photo:'',isGeneral:false})));CS_save();CS_renderActivity();toast(CS_t('templateUsed'));}
function CS_completeActivity(){const activityId=projectBrain.construction.selectedActivity;const applicable=CS_checkRows(activityId).filter(x=>x.status!=='na');if(applicable.some(x=>x.status!=='compliant')){toast(CS_lang()==='ar'?'أكمل بنود الفحص المنطبقة وسجّل حالة مطابقة قبل الإغلاق.':'Complete applicable checklist items and mark them compliant before closure.');return;}projectBrain.construction.activityStatus=projectBrain.construction.activityStatus||{};projectBrain.construction.activityStatus[activityId]='complete';CS_save();CS_renderPhases();toast(CS_t('done'));}
function CS_records(){return projectBrain.construction.records||[];}
function CS_renderRecords(){
 const host=document.getElementById('csRecordList');if(!host)return;const ar=CS_lang()==='ar';const typeFilter=document.getElementById('csRecordFilter')?.value||'';const rows=CS_records().filter(x=>!typeFilter||x.type===typeFilter).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
 if(!rows.length){host.innerHTML=`<div class="cs-empty">${CS_t('emptyRecords')}</div>`;return;}
 host.innerHTML=rows.map(r=>{const cfg=CS_RECORDS[r.type]||CS_RECORDS.wbs;const title=r.title||(CS_lang()==='ar'?(r.fields?.taskAr||r.fields?.taskEn):(r.fields?.taskEn||r.fields?.taskAr)||r.fields?.activity||r.fields?.materialName||r.fields?.number||CS_t(cfg.title));const state=r.fields?.status||'pending';return `<details class="cs-record" data-record="${r.id}"><summary><span class="cs-record-kind">${cfg.icon}</span><span class="cs-record-title"><b>${CS_esc(title)}</b><small>${CS_esc(CS_t(cfg.title))} · ${CS_esc(r.fields?.building||r.fields?.location||r.fields?.date||CS_now())}</small></span><span class="cs-status-pill ${CS_esc(state)}">${CS_esc(CS_statusLabel(state))}</span></summary><div class="cs-record-body"><div class="cs-record-fields">${cfg.fields.filter(k=>r.fields?.[k]).map(k=>`<div><small>${CS_t(k)}</small><p>${CS_esc(r.fields[k])}</p></div>`).join('')}</div>${r.photos?.map(p=>`<img class="cs-photo-thumb" src="${p.data}" alt="${CS_t('photo')}">`).join('')||''}<div class="cs-row-actions"><button class="btn small" type="button" onclick="CS_editRecord('${r.id}')">${CS_t('edit')}</button><button class="btn small" type="button" onclick="CS_exportRecord('${r.id}')">${CS_t('export')}</button><button class="btn small" type="button" onclick="CS_deleteRecord('${r.id}')">${CS_t('remove')}</button><button class="btn small" type="button" onclick="CS_ai('record','${r.id}')">${CS_t('aiSummarize')}</button></div></div></details>`;}).join('');
}
function CS_statusLabel(status){const map={notStarted:'notStarted',inProgress:'inProgress',compliant:'compliant',nonCompliant:'nonCompliant',na:'na',pending:'pending',approved:'approved',rejected:'rejected',draft:'draft',complete:'done',closed:'done','inspection pending':'inspectionPending','response required':'responseNeeded'};return CS_t(map[status]||'pending');}
function CS_renderStats(){
 const c=projectBrain.construction||{};const rows=CS_records();const wbs=rows.filter(x=>x.type==='wbs');const average=wbs.length?Math.round(wbs.reduce((s,x)=>s+Math.min(100,Math.max(0,Number(x.fields.percent)||0)),0)/wbs.length):0;
 const stats={csStatActivities:CS_RAW.reduce((n,p)=>n+p.activities.length,0),csStatChecks:c.checklists?.length||0,csStatIR:rows.filter(x=>x.type==='ir'&&!['approved','complete','closed'].includes(x.fields?.status)).length,csStatIssues:rows.filter(x=>['ncr','rfi'].includes(x.type)&&!['approved','complete','closed'].includes(x.fields?.status)).length,csStatProgress:`${average}%`};
 for(const [id,value] of Object.entries(stats)){const el=document.getElementById(id);if(el)el.textContent=value;}
 const progress=document.getElementById('csWbsProgress');if(progress)progress.style.width=`${average}%`;
}
function CS_openForm(type,id=null){
 const cfg=CS_RECORDS[type];if(!cfg)return;const form=document.getElementById('csRecordForm');const box=document.getElementById('csRecordFields');if(!form||!box)return;
 const existing=id?CS_records().find(x=>x.id===id):null;document.getElementById('csFormType').value=type;document.getElementById('csEditId').value=id||'';
 const values=existing?.fields||{};box.innerHTML=cfg.fields.map(key=>CS_field(type,key,values[key]||'')).join('')+`<label class="cs-form-field cs-form-wide">${CS_t('photo')}<input id="csRecordPhotos" type="file" accept="image/*" multiple><small>${CS_t('photosOnly')}</small></label>`;
 form.classList.add('is-open');form.scrollIntoView({behavior:'smooth',block:'start'});const title=document.getElementById('csFormTitle');if(title)title.textContent=CS_t(cfg.title);document.getElementById('csFormSubmit').textContent=existing?CS_t('edit'):CS_t('save');
}
function CS_field(type,key,value){
 const date=['date','inspectionDate','reinspection','start','finish','actualStart','actualFinish','target'].includes(key);const number=['percent','manpower'].includes(key);const area=['question','response','consultantComments','corrective','preventive','rootCause','technicalData','delivery','scope','resources','sequence','risk','weather','subcontractors','equipment','performed','deliveries','inspections','technicalIssues','delays','qualityObs','safetyObs','remarks','tomorrow','referenceDocs','verification','drawing'].includes(key);
 let control='';if(key==='status'||key==='internalStatus'||key==='result'||key==='review'||key==='inspectReq'){
  const options=key==='status'?['notStarted','inProgress','pending','approved','rejected','complete','closed','response required','inspection pending']:key==='internalStatus'?['notStarted','inProgress','compliant','nonCompliant']:key==='result'?['pending','approved','rejected','response required']:key==='review'?['pending','approved','rejected','inProgress']:['Yes','No','pending'];
  control=`<select class="input" name="${key}">${options.map(o=>`<option value="${o}" ${value===o?'selected':''}>${CS_statusLabel(o)}</option>`).join('')}</select>`;
 }else if(key==='discipline')control=`<select class="input" name="${key}">${['Architecture','Structure','MEP','Fire & Life Safety','Civil','Landscape','Specialist'].map(o=>`<option ${value===o?'selected':''}>${o}</option>`).join('')}</select>`;
 else if(key==='activity')control=`<select class="input" name="${key}"><option value="">—</option>${CS_RAW.flatMap(p=>p.activities.map(a=>`<option value="${CS_esc(a.en)}" ${value===a.en?'selected':''}>${CS_esc(a[CS_lang()])}</option>`)).join('')}</select>`;
 else control=area?`<textarea class="input" name="${key}" rows="${key==='question'||key==='performed'||key==='sequence'?3:2}">${CS_esc(value)}</textarea>`:`<input class="input" type="${date?'date':number?'number':'text'}" ${number?'min="0" max="100"':''} name="${key}" value="${CS_esc(value)}" ${number?'placeholder="0"':''}>`;
 return `<label class="cs-form-field ${area?'cs-form-wide':''}">${CS_t(key)}${control}</label>`;
}
async function CS_saveRecord(event){
 event.preventDefault();const form=document.getElementById('csRecordForm'),type=document.getElementById('csFormType').value,id=document.getElementById('csEditId').value;const fields={};new FormData(form).forEach((v,k)=>{if(k&&!['recordType','editId'].includes(k))fields[k]=String(v).trim();});
 if(type==='ir'&&!fields.number)fields.number=`IR-${String(Date.now()).slice(-6)}`;if(type==='rfi'&&!fields.number)fields.number=`RFI-${String(Date.now()).slice(-6)}`;if(type==='ncr'&&!fields.number)fields.number=`NCR-${String(Date.now()).slice(-6)}`;if(type==='daily'&&!fields.date)fields.date=CS_now();if(type==='wbs')fields.percent=Math.min(100,Math.max(0,Number(fields.percent)||0));
 if(type==='method')fields.status='draft';const photoFiles=[...(document.getElementById('csRecordPhotos')?.files||[])];if(photoFiles.length>4){toast(CS_t('photosOnly'));return;}const photos=[];for(const file of photoFiles){try{photos.push({name:file.name,data:await CS_compressPhoto(file)});}catch{toast(CS_t('photosOnly'));return;}}
 const existing=id?CS_records().find(x=>x.id===id):null;const item={id:id||CS_uid(),type,fields,photos:photos.length?photos:(existing?.photos||[]),updatedAt:new Date().toISOString(),createdAt:existing?.createdAt||new Date().toISOString()};
 projectBrain.construction.records=existing?CS_records().map(x=>x.id===id?item:x):[item,...CS_records()];CS_save();form.classList.remove('is-open');form.reset();CS_renderRecords();CS_renderProgress();toast(existing?CS_t('updated'):CS_t('saved'));
}
async function CS_compressPhoto(file){if(!file.type.startsWith('image/'))throw Error('image required');if(file.size>8*1024*1024)throw Error('image too large');const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=reject;el.src=url;});const scale=Math.min(1,1300/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const out=canvas.toDataURL('image/jpeg',.72);if(out.length>1_350_000)throw Error('compressed image too large');return out;}
function CS_editRecord(id){const r=CS_records().find(x=>x.id===id);if(r)CS_openForm(r.type,id);}
function CS_deleteRecord(id){if(!confirm(CS_t('confirmDelete')))return;projectBrain.construction.records=CS_records().filter(x=>x.id!==id);CS_save();CS_renderRecords();CS_renderProgress();toast(CS_t('deleted'));}
function CS_exportRecord(id){const r=CS_records().find(x=>x.id===id);if(!r)return;const cfg=CS_RECORDS[r.type];const locale=document.getElementById('csReportLanguage')?.value||projectBrain.construction.preferences.reportLanguage||'bilingual';const ar=locale!=='en',en=locale!=='ar';const label=(key)=>locale==='bilingual'?`${CS_TX.en[key]||key} / ${CS_TX.ar[key]||key}`:CS_TX[locale==='ar'?'ar':'en'][key]||key;const title=label(cfg.title),report=label('reportTitle'),warning=label('notApproval'),guidance=label('guidance');const body=cfg.fields.filter(k=>r.fields?.[k]).map(k=>`<tr><th>${CS_esc(label(k))}</th><td>${CS_esc(r.fields[k]).replace(/\n/g,'<br>')}</td></tr>`).join('');const dir=locale==='bilingual'?'auto':ar?'rtl':'ltr';const html=`<!doctype html><html lang="${locale==='ar'?'ar':'en'}" dir="${dir}"><meta charset="utf-8"><title>${CS_esc(report)} — ${CS_esc(title)}</title><style>body{font:14px Arial,sans-serif;max-width:920px;margin:32px auto;padding:16px;color:#171717}h1,h2{font-weight:400}header,footer{border-block:1px solid #888;padding:14px 0}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{text-align:start;vertical-align:top;padding:10px;border-bottom:1px solid #ddd}th{width:30%;color:#555}.warn{background:#f3f0e8;padding:12px}@media print{button{display:none}}</style><header><b>ARCHMIND</b> · ${CS_esc(report)}</header><h1>${CS_esc(title)} · ${CS_esc(r.fields?.number||r.fields?.date||r.id)}</h1><p>${CS_esc(projectBrain.name||'ARCHMIND')} · ${CS_esc(projectBrain.location||'')}</p><table>${body}</table>${r.photos?.map(p=>`<figure><img src="${p.data}" style="max-width:100%;max-height:340px"><figcaption>${CS_esc(p.name)}</figcaption></figure>`).join('')||''}<p class="warn">${CS_esc(warning)}<br>${CS_esc(guidance)}</p><footer>${new Date().toLocaleString()}</footer></html>`;const blob=new Blob([html],{type:'text/html;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ARCHMIND-${r.type}-${r.fields?.number||r.id}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function CS_renderProgress(){const host=document.getElementById('csProgressRows');if(!host)return;const rows=CS_records().filter(x=>x.type==='wbs');if(!rows.length){host.innerHTML=`<p class="cs-empty">${CS_t('wbsEmpty')}</p>`;return;}const by=rows.reduce((acc,r)=>{const key=[r.fields.building,r.fields.level,r.fields.zone,r.fields.discipline,r.fields.package].filter(Boolean).join(' / ')||CS_t('wbs');(acc[key]||=[]).push(r);return acc;},{});host.innerHTML=Object.entries(by).map(([group,items])=>`<section class="cs-wbs-group"><h3>${CS_esc(group)}</h3>${items.map(r=>`<div class="cs-wbs-row"><div><b>${CS_esc(CS_lang()==='ar'?(r.fields.taskAr||r.fields.taskEn):(r.fields.taskEn||r.fields.taskAr)||CS_t('wbs'))}</b><small>${CS_esc(r.fields.owner||'—')} · ${CS_esc(r.fields.start||'—')} → ${CS_esc(r.fields.finish||'—')}</small></div><label><input type="number" min="0" max="100" value="${Number(r.fields.percent)||0}" onchange="CS_setPercent('${r.id}',this.value)"> %</label><span class="cs-status-pill ${CS_esc(r.fields.status||'pending')}">${CS_esc(CS_statusLabel(r.fields.status||'pending'))}</span></div>`).join('')}</section>`).join('');}
function CS_setPercent(id,value){const r=CS_records().find(x=>x.id===id);if(!r)return;r.fields.percent=Math.min(100,Math.max(0,Number(value)||0));r.updatedAt=new Date().toISOString();CS_save();CS_renderProgress();}
function CS_ai(action,recordId){
 const prefs=projectBrain.construction.preferences||{};const data=CS_activity(projectBrain.construction.selectedActivity);const record=recordId?CS_records().find(x=>x.id===recordId):null;const level=CS_t(prefs.explanationLevel||'professional');const lang=prefs.aiLanguage==='ar'?'Arabic':prefs.aiLanguage==='en'?'English':CS_lang()==='ar'?'Arabic':'English';let task='';
 if(action==='activity'&&data)task=`Explain the construction activity ${data.activity.en} (${data.activity.ar}) in ${lang} at ${level} level. Include what it is, why it is needed, typical documents/materials, a safe general sequence, quality/inspection checks, coordination, completion evidence and next activity. Mark project-specific unknowns. Distinguish contractor self-check from consultant, authority and third-party inspection.`;
 else if(action==='translate')task=`Explain/translate the currently selected activity and its stored checklist in ${lang}. Preserve original wording and technical abbreviations; explain IFC, IR, RFI, NCR, ITP, BOQ, HVAC and MEP when first used.`;
 else if(record)task=`Review this ${record.type} site record and summarize it in ${lang} at ${level} level. Identify missing information and suggested follow-up. Preserve every supplied fact; do not invent approvals, dimensions, references, code clauses or contract requirements. Label all draft wording as subject to project review.\n${JSON.stringify(record,null,2)}`;
 else task=`Summarize the current site report or construction log in ${lang}; identify missing data and organize facts, observations, risks and proposed follow-up separately. Do not create approvals or unrecorded facts. Level: ${level}.`;
 CS_tab('chat');const input=document.getElementById('csChatInput');if(input){input.value=task;input.focus();}
}
let CS_pendingFiles=[];
function CS_chatContext(){const c=projectBrain.construction||{};return {...projectBrain,construction:{selectedActivity:c.selectedActivity,activityStatus:c.activityStatus,preferences:c.preferences,checklists:(c.checklists||[]).map(({photo,...x})=>x).slice(-40),records:(c.records||[]).map(({photos,...x})=>x).slice(-30),chatHistory:(c.chatHistory||[]).slice(-10)}};}
function CS_renderChat(){const host=document.getElementById('csChatMessages');if(!host)return;host.innerHTML=(projectBrain.construction.chatHistory||[]).map(m=>`<article class="cs-chat-message ${m.role==='user'?'is-user':'is-ai'}"><div class="cs-chat-role">${m.role==='user'?(CS_lang()==='ar'?'أنت':'You'):'ARCHMIND · '+CS_t('aiTitle')}</div><div>${CS_esc(m.content||'').replace(/\n/g,'<br>')}</div>${m.attachments?.length?`<small>${CS_esc(m.attachments.map(a=>a.name).join(' · '))}</small>`:''}</article>`).join('');host.scrollTop=host.scrollHeight;}
function CS_renderPending(){const host=document.getElementById('csChatAttachments');if(!host)return;host.innerHTML=CS_pendingFiles.map((f,i)=>`<span class="cs-attachment-chip">${CS_esc(f.name)} <button type="button" aria-label="${CS_t('removeFile')}" onclick="CS_removePending(${i})">×</button></span>`).join('');}
function CS_removePending(i){CS_pendingFiles.splice(i,1);CS_renderPending();}
async function CS_readChatFile(file){const allowed=['image/png','image/jpeg','image/webp','application/pdf','text/plain','text/markdown','text/csv','application/json'];if(!allowed.includes(file.type))throw Error(CS_t('fileLimit'));if(file.size>6*1024*1024)throw Error(CS_t('fileLimit'));if(file.type.startsWith('image/'))return {name:file.name,mimeType:file.type,dataUrl:await CS_compressPhoto(file)};if(['text/plain','text/markdown','text/csv','application/json'].includes(file.type)){if(file.size>1024*1024)throw Error(CS_t('fileLimit'));return {name:file.name,mimeType:file.type,text:await file.text()};}return {name:file.name,mimeType:file.type,dataUrl:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);})};}
async function CS_submitChat(event){event.preventDefault();const input=document.getElementById('csChatInput');const text=input.value.trim();if(!text&&!CS_pendingFiles.length)return;const files=CS_pendingFiles.slice();const payloadMessage={role:'user',content:text||CS_t('fileReady'),attachments:files};const prior=(projectBrain.construction.chatHistory||[]).slice(-8);const requestMessages=[...prior.map(m=>({role:m.role,content:m.content})),payloadMessage];projectBrain.construction.chatHistory=[...prior,{role:'user',content:payloadMessage.content,attachments:files.map(({name,mimeType})=>({name,mimeType}))}].slice(-10);CS_renderChat();input.value='';CS_pendingFiles=[];CS_renderPending();const send=document.getElementById('csChatSend');if(send)send.disabled=true;const placeholder={role:'assistant',content:CS_t('thinking')};projectBrain.construction.chatHistory.push(placeholder);CS_renderChat();
 try{const selected=document.getElementById('csChatProvider')?.value;const chosen=selected||(localStorage.getItem('archmindProvider')||'gemini');const context=CS_chatContext();const pref=projectBrain.construction.preferences||{};context.constructionResponseLanguage=pref.aiLanguage==='ar'?'Arabic':pref.aiLanguage==='en'?'English':CS_lang()==='ar'?'Arabic':'English';context.constructionExplanationLevel=pref.explanationLevel||'professional';context.constructionSafety='Treat AI suggestions as draft only. Follow approved project documents and responsible professional judgment.';const r=await fetch('/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:chosen,mode:'site_engineer',messages:requestMessages,project:context})});let answer='';if((r.headers.get('content-type')||'').includes('text/plain')){if(!r.ok)throw Error(CS_t('chatError'));const reader=r.body.getReader(),decoder=new TextDecoder();while(true){const {value,done}=await reader.read();if(done)break;answer+=decoder.decode(value,{stream:true});placeholder.content=answer;CS_renderChat();}}else{const d=await r.json();if(!r.ok)throw Error(d.error||CS_t('chatError'));answer=d.text||CS_t('chatError');placeholder.content=answer;}if(!answer)throw Error(CS_t('chatError'));}catch(error){placeholder.content=CS_t('chatError')+'\n'+String(error.message||'');}finally{projectBrain.construction.chatHistory=(projectBrain.construction.chatHistory||[]).slice(-10);CS_save();CS_renderChat();if(send)send.disabled=false;}}
function CS_chatSuggestion(kind){const input=document.getElementById('csChatInput');if(!input)return;const map={activity:'activityPrompt',inspection:'inspectionPrompt',daily:'dailyPrompt',missing:'missingPrompt'};input.value=CS_t(map[kind]||'activityPrompt');CS_tab('chat');input.focus();}
async function CS_loadProviders(){const status=document.getElementById('csProviderStatus'),select=document.getElementById('csChatProvider');if(!select)return;try{const r=await fetch('/api/config');if(!r.ok)throw Error();const cfg=await r.json();for(const option of select.options)option.disabled=!cfg.available?.[option.value];const preferred=cfg.defaultProvider;if(preferred&&select.querySelector(`option[value="${preferred}"]`)&&!select.querySelector(`option[value="${preferred}"]`).disabled)select.value=preferred;const cloud=['openai','anthropic','gemini'].some(k=>cfg.available?.[k]);if(status)status.textContent=cloud?'':CS_t('providerHelp');}catch{if(status)status.textContent=CS_t('providerHelp');}}
function CS_recordTypeOptions(){const select=document.getElementById('csRecordFilter');if(select){const value=select.value;select.innerHTML=`<option value="">${CS_t('allRecords')}</option>${Object.entries(CS_RECORDS).map(([k,v])=>`<option value="${k}">${CS_t(v.title)}</option>`).join('')}`;select.value=value;}const phase=document.getElementById('csPhaseFilter');if(phase){const value=phase.value;phase.innerHTML=`<option value="">${CS_t('all')}</option>${CS_RAW.map(p=>`<option value="${p.id}">${CS_esc(p[CS_lang()])}</option>`).join('')}`;phase.value=value;}}
Object.assign(CS_TX.en,{quickGuideTitle:'Quick guide · execute, inspect, record'});
Object.assign(CS_TX.ar,{quickGuideTitle:'دليل سريع · نفّذ وافحص وسجّل'});
function CS_renderQuickGuide(){const host=document.getElementById('csQuickGuide');if(!host)return;const cards=currentLang==='ar'?[['١ · قبل التنفيذ','راجع آخر مراجعة معتمدة، المنهجية وITP، اعتماد المواد، التصاريح، جاهزية الموقع، والتنسيق مع التخصصات. حدّد نقاط التوقف قبل بدء النشاط.'],['٢ · أثناء التنفيذ','نفّذ بالتسلسل المعتمد وبالمواد والعينة المعتمدتين. راقب الأبعاد والمناسيب والمحاور وحماية الأعمال والتداخلات. سجّل أي اختلاف وارفع RFI عند غموض التصميم.'],['٣ · الفحص والاستلام','أكمل فحص المقاول الداخلي ثم ارفع IR في الموعد المحدد. عند Hold Point لا تُغطِّ العمل ولا تتجاوز المرحلة قبل موافقة الاستشاري المكتوبة. وثّق الملاحظات وأعد الفحص بعد التصحيح.'],['٤ · الإغلاق والتوثيق','سجّل النتيجة والصور والمراجع وردود الاستشاري. حدّث الرسومات والسجلات، واربط NCR والإجراء التصحيحي بدليل إغلاق واضح.']]:[['01 · Before work','Check the latest approved revision, method statement and ITP, approved materials, permits, site readiness, and trade coordination. Identify hold points before starting.'],['02 · Execute','Follow the approved sequence, materials and mock-up. Monitor setting-out, dimensions, levels, protection and interfaces. Record deviations and raise an RFI when design intent is unclear.'],['03 · Inspect & accept','Complete the contractor’s internal check, then raise the IR at the required time. At a Hold Point, do not cover or proceed before written consultant release. Record comments and re-inspect after correction.'],['04 · Close the record','Log the result, photos, drawing references and consultant response. Update controlled drawings and registers; link any NCR and corrective action to closure evidence.']];host.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px">${cards.map(([title,text])=>`<article class="cs-guide-card"><b>${CS_esc(title)}</b><p>${CS_esc(text)}</p></article>`).join('')}</div><p class="cs-small-note" style="margin-top:10px">${CS_esc(CS_t('inspectCaution'))}</p>`;}
function CS_render(){CS_initState();CS_renderNav();CS_renderQuickGuide();CS_recordTypeOptions();CS_renderActivity();CS_renderPhases();CS_renderRecords();CS_renderProgress();CS_renderStats();CS_renderChat();CS_renderPending();const prefs=projectBrain.construction.preferences||{};const l=document.getElementById('csAiLanguage'),r=document.getElementById('csReportLanguage'),e=document.getElementById('csLevel');if(l)l.value=prefs.aiLanguage||CS_lang();if(r)r.value=prefs.reportLanguage||'bilingual';if(e)e.value=prefs.explanationLevel||'professional';}
function CS_tab(name){document.getElementById('csActiveTab').value=name;document.querySelectorAll('[data-cs-panel]').forEach(p=>p.hidden=p.dataset.csPanel!==name);CS_renderTabs();if(name==='progressTab')CS_renderProgress();}
function CS_savePrefs(){projectBrain.construction.preferences.aiLanguage=document.getElementById('csAiLanguage').value;projectBrain.construction.preferences.reportLanguage=document.getElementById('csReportLanguage').value;projectBrain.construction.preferences.explanationLevel=document.getElementById('csLevel').value;CS_save();}
document.addEventListener('DOMContentLoaded',()=>{
 CS_render();document.getElementById('csRecordForm')?.addEventListener('submit',CS_saveRecord);
 document.getElementById('csSearch')?.addEventListener('input',CS_renderPhases);document.getElementById('csPhaseFilter')?.addEventListener('change',CS_renderPhases);document.getElementById('csStatusFilter')?.addEventListener('change',CS_renderPhases);document.getElementById('csRecordFilter')?.addEventListener('change',CS_renderRecords);
 document.querySelectorAll('[data-cs-tab]').forEach(b=>b.addEventListener('click',()=>CS_tab(b.dataset.csTab)));
 document.querySelectorAll('[data-cs-new]').forEach(b=>b.addEventListener('click',()=>CS_openForm(b.dataset.csNew)));
 document.getElementById('csAiLanguage')?.addEventListener('change',CS_savePrefs);document.getElementById('csReportLanguage')?.addEventListener('change',CS_savePrefs);document.getElementById('csLevel')?.addEventListener('change',CS_savePrefs);
 CS_tab('workflow');const cp=document.getElementById('csChatProvider');if(cp){const saved=localStorage.getItem('archmindProvider');if(saved&&cp.querySelector(`option[value="${saved}"]`))cp.value=saved;}CS_loadProviders();document.getElementById('csChatForm')?.addEventListener('submit',CS_submitChat);document.getElementById('csChatFiles')?.addEventListener('change',async e=>{const list=[...(e.target.files||[])];e.target.value='';if(list.length+CS_pendingFiles.length>4){toast(CS_t('fileLimit'));return;}try{for(const f of list){const item=await CS_readChatFile(f);const current=CS_pendingFiles.reduce((n,x)=>n+(x.dataUrl?Math.ceil(x.dataUrl.length*.75):new Blob([x.text||'']).size),0);const bytes=item.dataUrl?Math.ceil(item.dataUrl.length*.75):new Blob([item.text||'']).size;if(current+bytes>6*1024*1024)throw Error(CS_t('fileLimit'));CS_pendingFiles.push(item);}CS_renderPending();}catch(err){toast(err.message||CS_t('fileLimit'));}});const ci=document.getElementById('csChatInput');ci?.addEventListener('input',()=>{ci.style.height='auto';ci.style.height=Math.min(ci.scrollHeight,180)+'px';});
});
